import base64, json, os, time
import requests

BASE = "https://api.pagar.me/core/v5"
SECRET_KEY = os.environ["PAGARME_SECRET_KEY"]  # sk_test_... (teste) ou sk_... (producao)
AUTH = (SECRET_KEY, "")  # Basic: usuario = secret key, senha vazia


def _req(metodo, caminho, **kw):
    for tentativa in range(4):
        r = requests.request(metodo, BASE + caminho, auth=AUTH, timeout=30, **kw)
        if r.status_code == 429 or r.status_code >= 500:
            time.sleep(2 ** tentativa)
            continue
        if not r.ok:
            raise RuntimeError(f"HTTP {r.status_code}: {r.text[:500]}")
        return r.json() if r.content else {}
    raise RuntimeError("limite de tentativas excedido")


def executar(corpo: dict):
    """Criar cliente — ESCRITA: nunca execute em produção sem confirmação do responsável."""
    return _req("POST", f"/customers", json=corpo)


if __name__ == "__main__":
    print(json.dumps({"name": "Empresa Exemplo Ltda", "email": "financeiro@example.com", "document": "00000000000191", "document_type": "CNPJ", "type": "company", "code": "ERP-CLI-1042", "address": {"line_1": "1000, Av. Exemplo, Centro", "line_2": "Sala 12", "zip_code": "01310930", "city": "São Paulo", "state": "SP", "country": "BR"}, "phones": {"mobile_phone": {"country_code": "55", "area_code": "11", "number": "900000000"}}, "metadata": {"id_erp": "1042"}}, ensure_ascii=False, indent=2))

