// Node 18+ (fetch nativo)
const BASE = "https://api.pagar.me/core/v5";
const SECRET_KEY = process.env.PAGARME_SECRET_KEY!; // sk_test_... ou sk_...
const AUTH = "Basic " + Buffer.from(`${SECRET_KEY}:`).toString("base64");

async function req(metodo: string, caminho: string, body?: unknown, extraHeaders: Record<string, string> = {}) {
  for (let t = 0; t < 4; t++) {
    const r = await fetch(BASE + caminho, {
      method: metodo,
      headers: { Authorization: AUTH, "Content-Type": "application/json", ...extraHeaders },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    if (r.status === 429 || r.status >= 500) { await new Promise(s => setTimeout(s, 2 ** t * 1000)); continue; }
    if (!r.ok) throw new Error(`HTTP ${r.status}: ${(await r.text()).slice(0, 500)}`);
    return r.status === 204 ? {} : await r.json();
  }
  throw new Error("limite de tentativas excedido");
}

// Criar cliente — ESCRITA: confirme com o responsável antes de rodar em produção
export async function executar(corpo: unknown) {
  return req("POST", `/customers`, corpo);
}

