    });
    if (r.status === 429 || r.status >= 500) { await new Promise(s => setTimeout(s, 2 ** t * 1000)); continue; }
    if (!r.ok) throw new Error(`HTTP ${r.status}: ${(await r.text()).slice(0, 500)}`);
    return r.status === 204 ? {} : await r.json();
  }
  throw new Error("limite de tentativas excedido");
}

// Listar clientes — percorre todas as páginas
export async function listar(filtros: Record<string, string> = {}) {
  const itens: unknown[] = [];
  for (let pagina = 1; ; pagina++) {
    const qs = new URLSearchParams({ ...filtros, page: String(pagina), size: "100" });
    const r: any = await req("GET", `/customers?${qs}`);
    const lote = r.data ?? [];
    itens.push(...lote);
    if (lote.length < 100) return itens;
  }
}

